 where wt.id = e.worksheet_template_id and s.code = 'DIN-EN-16941-2'
   and e.id in ('72c7d660-c4c2-42a5-a67f-702dd6de6706','4e9bae2a-d1b9-43d9-975f-b56e99395557')
